for es,en,b,be in [('Flow · Pagos','Flow · Payments','Conector desarrollado y configuración sandbox documentada. La operación productiva y el plan mensual requieren credenciales y definición comercial.','Connector developed and sandbox setup documented. Production operation and the monthly plan require credentials and commercial configuration.'),('Google, Facebook, Instagram y Canva','Google, Facebook, Instagram and Canva','Flujos implementados. La disponibilidad depende de cuentas autorizadas, permisos, configuración y revisión de cada proveedor.','Flows implemented. Availability depends on authorised accounts, permissions, setup and each provider’s review.'),('Despacho y Starken','Shipping and Starken','Cálculo con tarifas registradas. La cotización automática con el transportista requiere acceso a su API.','Calculation with registered rates. Automatic carrier quotes require API access.'),('VPS y continuidad','VPS and continuity','Variante Docker/Caddy y procedimientos de migración preparados. No se presenta como una migración a VPS ya completada.','Docker/Caddy variant and migration procedures prepared. This is not presented as an already completed VPS migration.')]:html+='<details><summary>'+t(es,en)+'</summary>'+t(b,be,'p')+'</details>'
