html+='<section class="section closing">'+t('TU NEGOCIO PUEDE SER EL SIGUIENTE','YOUR BUSINESS COULD BE NEXT','p','class="eyebrow"')+t('¿Qué necesitas\nconectar tú?','What do you need\nto connect?','h2')+link('../../index.html?proyecto=kraftdo#contacto','Construyamos tu proyecto ↗','Let’s build your project ↗')+'</section></main><footer>'+link('../../index.html','← Volver a Hefesto','← Back to Hefesto','back')+t('Fotografías oficiales de KraftDo · Caso de estudio de Hefesto Studio','Official KraftDo photographs · A Hefesto Studio case study','p')+link('../../index.html#plantillas','Explorar plantillas','Explore templates','back')+'</footer><script src="case.js?v=2"></script></body></html>'

